class Rect {
  constructor(w, h) { this.w = w; this.h = h; }
  setW(w) { this.w = w; }
  area() { return this.w * this.h; }
}
class Square extends Rect {
  constructor(s) { super(s, s); }
  setW(w) { this.w = w; this.h = w; }
}
function stretch(r) {
  r.setW(5);
  return r.area();
}
console.log(stretch(new Rect(2, 4)), stretch(new Square(4)));

