class OrderService {
  private repo = new PostgresOrderRepo();
  private mailer = new SesMailer(process.env.SES_REGION!);

  async place(order: Order) {
    await this.repo.save(order);
    await this.mailer.send(order.email, 'Thanks!');
  }
}
